def market_strip(b, name, src, stats):
    s = f'<div style="{ab(64, 146, 1152, 70, f"box-sizing: border-box; border-radius: 14px; background: {SOFT}; padding: 0 18px; display: flex; align-items: center; gap: 0")}">'
    s += ('<span style="display: flex; flex-direction: column; gap: 2px; width: 330px; flex-shrink: 0; min-width: 0">'
          + b.tb(name, f'font-size: 14px; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis')
          + b.tb(src, f'font-size: 11px; color: {MUTED}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis') + '</span>')
    for (lab, val, unit, note) in stats:
        s += (f'<span style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; padding: 0 16px; border-left: 1px solid {LINE}">'
              + b.tb(lab, f'font-size: 11px; font-weight: 700; color: {MUTED}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis')
              + '<span style="display: flex; align-items: baseline; gap: 3px; white-space: nowrap">' + b.tb(val, f'{NUM}; font-size: 20px; font-weight: 800; color: {INK}') + b.tb(unit, f'font-size: 12px; font-weight: 700; color: {INK}') + '</span>'
              + (b.tb(note, f'font-size: 10.5px; color: {FAINT}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis') if note else '') + '</span>')
    # mini trend bars (shape only — values live in the stats)
    s += f'<span style="width: 132px; flex-shrink: 0; height: 46px; display: flex; align-items: flex-end; gap: 6px; padding-left: 16px; border-left: 1px solid {LINE}">'
    for k, hh in enumerate([16, 20, 24, 29, 35, 42]):
        s += f'<i style="flex: 1; height: {hh}px; border-radius: 3px 3px 0 0; background: {BLUE if k == 5 else "#c5cde6"}"></i>'
    s += '</span></div>'
    return s


def trend_cards(b, cust, trends, y=230):
    s = ''
    for i, (t, d, so, metric, pid, pos) in enumerate(trends):
        x = 64 + i * 292
        s += photo(b, pid, x, y, 276, 176, pos=pos, hint=f'흐름 {i + 1} · {t} 현장 사진')
        s += b.tb(f'{i + 1:02d}', ab(x + 10, y + 10, 30, 24, f'border-radius: 8px; background: {BLUE}; color: #fff; font-size: 12px; font-weight: 800; display: flex; align-items: center; justify-content: center; {NUM}'), 'div')
        s += b.tb(t, ab(x, y + 188, 276, 42, f'font-size: 15.5px; font-weight: 800; line-height: 1.35; {clamp(2)}'), 'div')
        s += b.tb(d, ab(x, y + 234, 276, 57, f'font-size: 12.5px; line-height: 1.5; color: {BODY}; {clamp(3)}'), 'div')
        s += (f'<div style="{ab(x, y + 298, 276, 120, f"box-sizing: border-box; border-radius: 10px; background: {CHIP}; padding: 10px 12px; display: flex; flex-direction: column; gap: 4px")}">'
              + b.tb(f'그래서 {cust}에게', f'font-size: 11px; font-weight: 800; color: {BLUE}')
              + b.tb(so, f'font-size: 13px; font-weight: 800; line-height: 1.45; color: {INK}; {clamp(3)}')
              + (b.tb('지표 · ' + metric, f'margin-top: auto; {NUM}; font-size: 11px; font-weight: 700; color: {MUTED}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis') if metric else '')
              + '</div>')
    return s


for code, (mname, msrc, stats, trends) in D.items():
    eb, hl, sub = _ORIG[f'L_MI_{code}_A']
    @layout(L, f=f'L_PH_MI_{code}_A', code=f'PH-MI-{code}-A', p='market', ind=code, name=f'{NAMES[code]} · 시장 · 트렌드 · 사진',
            when=f'{NAMES[code]} 고객사의 시장 규모와 업계를 움직이는 네 가지 흐름을, 흐름마다 현장 사진으로 보여줄 때',
            pv=[f'L_MI_{code}_A'], sample=CUST[code], grp='분석 · 이해')
    def _(b, code=code, eb=eb, hl=hl, sub=sub, mname=mname, msrc=msrc, stats=stats, trends=trends):
        s = header(b, eb, hl, sub, w=1152)
        s += market_strip(b, mname, msrc, stats)
        s += trend_cards(b, CUST[code], trends)
        s += footer(b, f'{DEAL[code]} · 수치는 예시 · 조사 / 실측 후 반영 · 사진: samsung.com {SRC[code]} 도입사례 · 비즈니스 페이지', 4)
        return s
